/**
 * Helpers for the Zig data generators in this directory.
 *
 * Each generator is a file `<name>.ts` exporting `files(): ZigFile[]`: Zig source generated
 * from the TypeScript's data (usually its `autogen.*.ts` tables), written under `zig/src/`.
 * The TypeScript stays the single source; `yarn zig-data` regenerates, and `yarn test` fails
 * if a generated file is stale. Files starting with `_` are helpers.
 */

export interface ZigFile {
  /** Path relative to `zig/src/`, e.g. `plurals/autogen.rules.zig`. */
  path: string;
  content: string;
}

/** A Zig string literal. UTF-8 is kept as is; quotes, backslashes and controls are escaped. */
export const zigString = (s: string): string => {
  let out = '"';
  for (const ch of s) {
    const c = ch.codePointAt(0)!;
    if (ch === '"') {
      out += '\\"';
    } else if (ch === '\\') {
      out += '\\\\';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (c < 0x20 || c === 0x7f) {
      out += `\\x${c.toString(16).padStart(2, '0')}`;
    } else {
      out += ch;
    }
  }
  return out + '"';
};

/** A Zig array of string literals, one per line. */
export const zigStringArray = (xs: readonly string[], indent = '    '): string =>
  xs.length === 0 ? '&.{}' : `&.{\n${xs.map((x) => `${indent}${zigString(x)},`).join('\n')}\n}`;

const ZIG_KEYWORDS = new Set(
  (
    'addrspace align allowzero and anyframe anytype asm break callconv catch comptime const ' +
    'continue defer else enum errdefer error export extern fn for if inline linksection ' +
    'noalias noinline nosuspend opaque or orelse packed pub resume return struct suspend ' +
    'switch test threadlocal try union unreachable usingnamespace var volatile while'
  ).split(' '),
);

/** An identifier, quoted as @"..." when needed (e.g. `en-US`, `type`). */
export const zigIdent = (s: string): string =>
  /^[A-Za-z_][A-Za-z0-9_]*$/.test(s) && !ZIG_KEYWORDS.has(s) ? s : `@${zigString(s)}`;

/** Header for a generated file. */
export const header = (generator: string, source: string): string =>
  `// Generated by packages/hereabouts/scripts/zig/${generator}.ts from ${source}.\n` +
  '// Do not edit: run `yarn zig-data` instead.\n\n';
